diapositivas.css:
.lz { margin-top: 30px; }
.lz .tl { position: relative; height: 300px; }
.lz .tl-eje { position: absolute; left: 2%; right: 2%; top: 150px; height: 2px; background: color-mix(in srgb, var(--medio) 70%, transparent); }
.lz .hito { position: absolute; width: 300px; }
.lz .hito .punto { position: absolute; left: 50%; transform: translateX(-50%); width: 14px; height: 14px; border-radius: 50%; background: var(--acento); }
.lz .hito.arriba { top: 8px; height: 134px; }
.lz .hito.arriba .punto { bottom: -15px; }
.lz .hito.abajo { top: 172px; }
.lz .hito.abajo .punto { top: -29px; }
.lz .hito .tarjeta-tl { border: 1px solid color-mix(in srgb, var(--medio) 60%, transparent); padding: 16px 20px; background: linear-gradient(180deg, var(--panel) 0%, transparent 170%); }
.lz .hito .ref-tl { font-size: 19px; font-weight: 700; color: var(--acento); letter-spacing: .06em; text-transform: uppercase; margin-bottom: 6px; }
.lz .hito .txt-tl { font-size: 21px; color: var(--claro1); line-height: 1.35; }
.lz .hito.arriba .tarjeta-tl { position: absolute; bottom: 26px; left: 0; right: 0; }
.lz .hito.abajo .tarjeta-tl { margin-top: 0; }
.lz .era { position: absolute; top: 158px; font-size: 18px; color: var(--medio); letter-spacing: .14em; padding-top: 10px; }
.lz .era.alta { top: 120px; padding-top: 0; }

.lz { margin-top: 24px; }
.lz .rad { position: relative; height: 350px; }
.lz .rad svg { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 0; }
.lz .rad svg line { stroke: var(--medio); stroke-width: 1; opacity: .55; }
.lz .centro-rad { position: absolute; left: 50%; top: 56%; transform: translate(-50%,-50%); width: 300px; text-align: center; border: 1px solid var(--acento); padding: 22px 18px; background: var(--panel); z-index: 1; }
.lz .centro-rad .t { font-size: 24px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--claro2); }
.lz .centro-rad .s { font-size: 19px; color: var(--medio); margin-top: 6px; }
.lz .sat { position: absolute; width: 270px; text-align: center; border: 1px solid color-mix(in srgb, var(--medio) 60%, transparent); padding: 15px; background: var(--panel); z-index: 1; }
.lz .sat .t { font-size: 21px; font-weight: 700; color: var(--acento); margin-bottom: 4px; }
.lz .sat .s { font-size: 19px; color: var(--claro1); font-style: italic; }
